import { createStore } from '../src/store.js';

export function storeWith(...users) {
  const store = createStore();
  for (const user of users) {
    store.addUser(user);
  }
  return store;
}

export function ann(overrides = {}) {
  return { email: 'ann@example.com', name: 'Ann Lee', role: 'member', ...overrides };
}
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { createUser } from '../src/handlers/createUser.js';
import { ann, storeWith } from './helpers.js';

test('creates a user with a trimmed, lowercase email and the default role', () => {
  const store = storeWith();
  const result = createUser(store, { body: { email: '  Ann@Example.com ', name: ' Ann Lee ' } });
  assert.equal(result.status, 201);
  assert.deepEqual(result.body, { id: 1, email: 'ann@example.com', name: 'Ann Lee', role: 'member' });
});

test('rejects a missing email', () => {
  const result = createUser(storeWith(), { body: { name: 'Ann Lee' } });
  assert.equal(result.status, 400);
  assert.deepEqual(result.body.messages, ['email is required']);
});

test('rejects an unknown role', () => {
  const result = createUser(storeWith(), { body: { email: 'ann@example.com', name: 'Ann', role: 'god' } });
  assert.deepEqual(result.body.messages, ['role is invalid']);
});

test('answers 409 when the email is taken', () => {
  const result = createUser(storeWith(ann()), { body: { email: 'ANN@example.com', name: 'Other Ann' } });
  assert.equal(result.status, 409);
  assert.equal(result.body.message, 'email already in use');
});
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { updateUser } from '../src/handlers/updateUser.js';
import { ann, storeWith } from './helpers.js';

test('changes only the fields that are present', () => {
  const store = storeWith(ann());
  const result = updateUser(store, { params: { id: '1' }, body: { name: ' Anna Lee ' } });
  assert.equal(result.status, 200);
  assert.deepEqual(result.body, { id: 1, email: 'ann@example.com', name: 'Anna Lee', role: 'member' });
});

test('answers 404 for an unknown user', () => {
  const result = updateUser(storeWith(), { params: { id: '7' }, body: { name: 'Ann' } });
  assert.equal(result.status, 404);
});

test('rejects a present but invalid email', () => {
  const result = updateUser(storeWith(ann()), { params: { id: '1' }, body: { email: 'nope' } });
  assert.deepEqual(result.body.messages, ['email is invalid']);
});

test('answers 409 when the email belongs to another user', () => {
  const store = storeWith(ann(), ann({ email: 'bob@example.com', name: 'Bob' }));
  const result = updateUser(store, { params: { id: '2' }, body: { email: 'Ann@example.com' } });
  assert.equal(result.status, 409);
});
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { inviteUser } from '../src/handlers/inviteUser.js';
import { ann, storeWith } from './helpers.js';

test('creates a pending invitation', () => {
  const result = inviteUser(storeWith(), { body: { email: ' bob@example.com ', name: 'Bob', role: 'viewer' } });
  assert.equal(result.status, 201);
  assert.deepEqual(result.body, { id: 1, email: 'bob@example.com', name: 'Bob', role: 'viewer', status: 'pending' });
});

test('requires a role', () => {
  const result = inviteUser(storeWith(), { body: { email: 'bob@example.com' } });
  assert.deepEqual(result.body.messages, ['role is required']);
});

test('answers 409 when a user already has the email', () => {
  const result = inviteUser(storeWith(ann()), { body: { email: 'ann@example.com', role: 'member' } });
  assert.equal(result.status, 409);
});
export function createStore() {
  const users = new Map();
  const invitations = [];
  let nextUserId = 1;
  let nextInvitationId = 1;

  return {
    listUsers() {
      return [...users.values()];
    },
    getUser(id) {
      return users.get(id);
    },
    findUserByEmail(email) {
      return [...users.values()].find((user) => user.email === email);
    },
    addUser(fields) {
      const user = { id: nextUserId++, ...fields };
      users.set(user.id, user);
      return user;
    },
    updateUser(id, changes) {
      const user = { ...users.get(id), ...changes };
      users.set(id, user);
      return user;
    },
    removeUser(id) {
      users.delete(id);
    },
    findInvitationByEmail(email) {
      return invitations.find((invitation) => invitation.email === email);
    },
    addInvitation(fields) {
      const invitation = { id: nextInvitationId++, ...fields, status: 'pending' };
      invitations.push(invitation);
      return invitation;
    },
  };
}
